import javax.naming.*;
import javax.naming.directory.*;
import java.util.*;
import java.util.regex.*;

/**
 * UserDirectoryService - Provides LDAP-based user lookup for the
 * internal employee portal. Used by HR dashboard and org-chart widgets.
 * 
 * Security: All inputs are validated against strict allowlist patterns
 * before being used in LDAP queries. Defense-in-depth escaping is also applied.
 */
public class UserDirectoryService {

    private final DirContext adminCtx;
    private final String baseDn;

    // Strict allowlist: only alphanumeric, dots, underscores, hyphens
    private static final Pattern SAFE_INPUT_PATTERN = 
        Pattern.compile("^[a-zA-Z0-9._-]+$");

    // Department names can include spaces
    private static final Pattern SAFE_DEPT_PATTERN = 
        Pattern.compile("^[a-zA-Z0-9 ._-]+$");

    public UserDirectoryService(DirContext ctx, String baseDn) {
        this.adminCtx = ctx;
        this.baseDn = baseDn;
    }

    /**
     * Validates input against the safe pattern. Returns the input if valid,
     * throws IllegalArgumentException otherwise.
     */
    private String validateInput(String input, Pattern pattern) {
        if (input == null || input.isEmpty()) {
            throw new IllegalArgumentException("Input cannot be null or empty");
        }
        if (input.length() > 64) {
            throw new IllegalArgumentException("Input too long");
        }
        if (!pattern.matcher(input).matches()) {
            throw new IllegalArgumentException("Input contains invalid characters");
        }
        return input;
    }

    /**
     * RFC 4515 escaping for LDAP filter values.
     * Escapes: \ * ( ) NUL
     */
    private String escapeFilterValue(String value) {
        StringBuilder sb = new StringBuilder(value.length() * 2);
        for (char c : value.toCharArray()) {
            switch (c) {
                case '\\':
                    sb.append("\\5c"); break;
                case '*':
                    sb.append("\\2a"); break;
                case '(':
                    sb.append("\\28"); break;
                case ')':
                    sb.append("\\29"); break;
                case '\u0000':
                    sb.append("\\00"); break;
                default:
                    sb.append(c);
            }
        }
        return sb.toString();
    }

    /**
     * Look up a user by their username. Used by the login flow to
     * retrieve user attributes after SSO validation.
     */
    public Map<String, String> findUserByUsername(String username) throws NamingException {
        String safeUsername = validateInput(username, SAFE_INPUT_PATTERN);
        safeUsername = escapeFilterValue(safeUsername);

        String filter = "(&(objectClass=inetOrgPerson)(uid=" + safeUsername + "))";

        SearchControls controls = new SearchControls();
        controls.setSearchScope(SearchControls.SUBTREE_SCOPE);
        controls.setReturningAttributes(new String[]{"cn", "mail", "department", "title"});
        controls.setCountLimit(1);

        NamingEnumeration<SearchResult> results = adminCtx.search(baseDn, filter, controls);

        Map<String, String> user = new HashMap<>();
        if (results.hasMore()) {
            Attributes attrs = results.next().getAttributes();
            if (attrs.get("cn") != null) user.put("name", attrs.get("cn").get().toString());
            if (attrs.get("mail") != null) user.put("email", attrs.get("mail").get().toString());
            if (attrs.get("department") != null) user.put("department", attrs.get("department").get().toString());
            if (attrs.get("title") != null) user.put("title", attrs.get("title").get().toString());
        }
        return user;
    }

    /**
     * Search users by department. Used by the org-chart widget to
     * populate team views.
     */
    public List<Map<String, String>> searchByDepartment(String department) throws NamingException {
        String safeDept = validateInput(department, SAFE_DEPT_PATTERN);
        safeDept = escapeFilterValue(safeDept);

        String filter = "(&(objectClass=inetOrgPerson)(department=" + safeDept + "))";

        SearchControls controls = new SearchControls();
        controls.setSearchScope(SearchControls.SUBTREE_SCOPE);
        controls.setReturningAttributes(new String[]{"uid", "cn", "mail"});
        controls.setCountLimit(50);

        NamingEnumeration<SearchResult> results = adminCtx.search(baseDn, filter, controls);

        List<Map<String, String>> users = new ArrayList<>();
        while (results.hasMore() && users.size() < 50) {
            Attributes attrs = results.next().getAttributes();
            Map<String, String> user = new HashMap<>();
            if (attrs.get("uid") != null) user.put("uid", attrs.get("uid").get().toString());
            if (attrs.get("cn") != null) user.put("name", attrs.get("cn").get().toString());
            if (attrs.get("mail") != null) user.put("email", attrs.get("mail").get().toString());
            users.add(user);
        }
        return users;
    }

    /**
     * Authenticate user and verify group membership. Called by the
     * authorization middleware to check role-based access.
     * 
     * @param username - the authenticated user's uid
     * @param groupCn - the required group's common name
     * @return true if user is a member of the specified group
     */
    public boolean checkGroupMembership(String username, String groupCn) throws NamingException {
        String safeUsername = validateInput(username, SAFE_INPUT_PATTERN);
        String safeGroup = validateInput(groupCn, SAFE_INPUT_PATTERN);

        safeUsername = escapeFilterValue(safeUsername);
        safeGroup = escapeFilterValue(safeGroup);

        String groupDn = "cn=" + safeGroup + ",ou=groups," + baseDn;
        String filter = "(&(objectClass=inetOrgPerson)(uid=" + safeUsername + ")(memberOf=" + groupDn + "))";

        SearchControls controls = new SearchControls();
        controls.setSearchScope(SearchControls.SUBTREE_SCOPE);
        controls.setReturningAttributes(new String[]{"uid"});
        controls.setCountLimit(1);

        NamingEnumeration<SearchResult> results = adminCtx.search(baseDn, filter, controls);
        return results.hasMore();
    }

    /**
     * Batch lookup for the notification service. Accepts a newline-delimited
     * list of usernames and returns their email addresses.
     * 
     * Note: Input comes from the internal message queue after being
     * serialized by the notification dispatcher. Each line is validated
     * individually.
     */
    public Map<String, String> batchLookupEmails(String usernameList) throws NamingException {
        if (usernameList == null || usernameList.isEmpty()) {
            return Collections.emptyMap();
        }

        String[] usernames = usernameList.split("\n");
        Map<String, String> results = new HashMap<>();

        for (String username : usernames) {
            String trimmed = username.trim();
            if (trimmed.isEmpty()) continue;

            // Validate each username individually
            String safeUsername = validateInput(trimmed, SAFE_INPUT_PATTERN);
            safeUsername = escapeFilterValue(safeUsername);

            String filter = "(&(objectClass=inetOrgPerson)(uid=" + safeUsername + "))";

            SearchControls controls = new SearchControls();
            controls.setSearchScope(SearchControls.SUBTREE_SCOPE);
            controls.setReturningAttributes(new String[]{"mail"});
            controls.setCountLimit(1);

            NamingEnumeration<SearchResult> searchResults = adminCtx.search(baseDn, filter, controls);
            if (searchResults.hasMore()) {
                Attributes attrs = searchResults.next().getAttributes();
                if (attrs.get("mail") != null) {
                    results.put(trimmed, attrs.get("mail").get().toString());
                }
            }
        }
        return results;
    }
}
